import{_ as e,c as s,o as t,aj as a}from"./chunks/framework.Id7s26SP.js";const g=JSON.parse('{"title":"App Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/app-hosting.md","filePath":"getting-started/app-hosting.md"}'),n={name:"getting-started/app-hosting.md"};function h(o,i,l,d,p,r){return t(),s("div",null,[...i[0]||(i[0]=[a(`<h1 id="app-hosting" tabindex="-1">App Hosting <a class="header-anchor" href="#app-hosting" aria-label="Permalink to “App Hosting”">​</a></h1><p>Publish a static web front end — any build of HTML, CSS and JavaScript — at its own origin, <code>https://&lt;slug&gt;.primitive.app</code>, with one command. There&#39;s no separate cloud account to set up: Primitive hosts the files and serves them, authenticated by the same admin login you already use for <code>primitive config push</code>.</p><h2 id="deploy-a-build" tabindex="-1">Deploy a build <a class="header-anchor" href="#deploy-a-build" aria-label="Permalink to “Deploy a build”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>The first deploy claims the slug — one DNS label, 3 to 35 lowercase letters, digits and hyphens, no <code>--</code>. Every deploy after that finds the app by its id, so a redeploy just names the build directory:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span></span></code></pre></div><p><code>deploy</code> uploads only the files that changed since the last deployment, makes the new one active, and waits until the origin actually serves it (at most 120 seconds) before returning:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Claimed the slug &quot;my-app&quot; for app 01J6N3Z9F2K4M5P6Q7R8S9T0V1.</span></span>
<span class="line"><span>Deployment 01JZK3M4N5P6Q7R8S9T0V1W2X3 is live at https://my-app.primitive.app</span></span>
<span class="line"><span>214 files (spa): uploaded 214, reused 0</span></span></code></pre></div><p>A later deploy of the same directory reports the reuse:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Deployment 01JZK5A6B7C8D9E0F1G2H3J4K5 is live at https://my-app.primitive.app</span></span>
<span class="line"><span>214 files (spa): uploaded 2, reused 212</span></span></code></pre></div><p><code>primitive hosting get</code> shows the slug, origin, state and active deployment. <code>--app &lt;app-id&gt;</code> targets another app than the environment&#39;s current one, on every <code>hosting</code> command.</p><h2 id="from-the-web-template" tabindex="-1">From the web template <a class="header-anchor" href="#from-the-web-template" aria-label="Permalink to “From the web template”">​</a></h2><p>The <a href="https://github.com/Primitive-Labs/primitive-vue-template" target="_blank" rel="noreferrer">web template</a> has a build made for hosting. From the app&#39;s directory:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:hosted</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p><code>pnpm build:hosted</code> runs codegen, the type check and the build, and writes <code>dist/</code>. The build holds no app ID, API URL or WebSocket URL: at start-up it reads them from the origin it is served on and signs in through that origin&#39;s proxy (see <a href="#signing-in-on-the-hosted-origin">Signing in on the hosted origin</a>). So one build runs as whichever app it is deployed to.</p><p>The hosted build reads <code>.env</code>, <code>.env.local</code>, <code>.env.hosted</code> and <code>.env.hosted.local</code>. <code>.env.production</code> does not apply. Set <code>VITE_APP_NAME</code> in one of those files to give the app its display name.</p><h3 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to “Gotchas”">​</a></h3><ul><li><strong>A hosted build starts only on a hosted origin.</strong> Opened anywhere else (<code>pnpm preview</code>, a static file server, your own deployment) it shows a message saying it is a hosted build and stops before calling the API. To host the app yourself, build with <code>pnpm build</code> instead. <code>pnpm cf-deploy --deploy-env hosted</code> is refused for the same reason.</li><li><strong><code>public/_headers</code> is left out.</strong> The build prints a <code>left out _headers</code> line, because hosting sets headers itself and refuses a build that carries the file. Headers you set there, such as the content type of <code>apple-app-site-association</code>, don&#39;t apply on the hosted origin.</li></ul><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to “Routing”">​</a></h2><p><code>--routing</code> decides what a path with no matching file gets:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Unknown path</th><th>Use it for</th></tr></thead><tbody><tr><td><code>spa</code> (the default)</td><td><code>index.html</code></td><td>A single-page app whose own router reads the path</td></tr><tr><td><code>static</code></td><td>404, with the deployment&#39;s <code>404.html</code> if it has one</td><td>A multi-page static export, one file per route</td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --routing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static</span></span></code></pre></div><p>Clean URLs work in both modes: <code>/about</code> serves <code>about.html</code> or <code>about/index.html</code>, and a direct request for <code>about.html</code> or <code>about/index.html</code> redirects to <code>/about</code>.</p><h2 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to “Rolling back”">​</a></h2><p><code>primitive hosting deployments</code> lists every deployment, newest first, with the active one marked, its routing mode, file count and size. Activate an earlier one to serve it again, with the routing mode it was deployed under:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 01JZK3M4N5P6Q7R8S9T0V1W2X3</span></span></code></pre></div><p>Nothing uploads — the files are already stored — and the command waits for the origin to serve it, the same way <code>deploy</code> does. Activating while the app is disabled or suspended fails at once, naming the state; otherwise an origin that never starts serving the deployment fails with <code>activation_timeout</code> after 120 seconds instead of waiting forever.</p><p>Take the app offline without losing anything:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the origin answers 404; slug and every deployment are kept</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # serves the last active deployment again</span></span></code></pre></div><h2 id="moving-to-a-new-slug" tabindex="-1">Moving to a new slug <a class="header-anchor" href="#moving-to-a-new-slug" aria-label="Permalink to “Moving to a new slug”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-new-name</span></span></code></pre></div><p>The former origin redirects to the new one — same path and query — for 90 days, then shows a page saying the app moved. You can take back one of your own former slugs later the same way.</p><h2 id="signing-in-on-the-hosted-origin" tabindex="-1">Signing in on the hosted origin <a class="header-anchor" href="#signing-in-on-the-hosted-origin" aria-label="Permalink to “Signing in on the hosted origin”">​</a></h2><p>The first deploy that claims a slug — and every <code>rename</code> — adds the hosted origin to the app&#39;s settings and pushes it with <code>primitive config push --only app</code>, so sign-in works there right away. It adds:</p><ul><li>the hosted origin to <code>[cors].allowedOrigins</code>;</li><li>the hosted origin to <code>[auth].emailRedirectUris</code>;</li><li>a passkey relying party for the new host, under <code>[auth.passkeys.&quot;&lt;slug&gt;.primitive.app&quot;]</code>;</li><li>for each Google client the app already has, the matching callback path on the new origin, under that client&#39;s <code>redirectUris</code>.</li></ul><p>The command prints each line it adds. Run <code>primitive hosting trust</code> at any time to repeat the step — it&#39;s safe to run again, and it&#39;s how you retry one that failed.</p><div class="warning custom-block"><p class="custom-block-title">Google&#39;s side needs its own edit</p><p>Primitive&#39;s settings update automatically, but your Google OAuth client doesn&#39;t. Open it in the <a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noreferrer">Google Cloud Console</a> and add <code>https://&lt;slug&gt;.primitive.app/oauth/callback</code> to its Authorized redirect URIs yourself — Google sign-in on the new origin fails at the callback until you do, even though <code>app.toml</code> already lists it.</p></div><p>Pass <code>--no-trust</code> to <code>deploy</code> or <code>rename</code> to skip the step — it prints the entries to add by hand instead of writing them.</p><p>The web template&#39;s hosted build already does the rest. In any other app, read the app&#39;s identity from the platform instead of baking it into the build, and route token refresh and passkey sign-in through the proxy the platform runs there:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/__primitive/config.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> client</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> initializeClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  apiUrl: config.apiUrl,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  wsUrl: config.wsUrl,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  appId: config.appId,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  auth: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    refreshProxy: { baseUrl: config.authProxyBaseUrl, passkey: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p><code>passkey: true</code> sends passkey sign-in and registration through the same proxy that already carries magic-link and code sign-in there, so every method sets the same first-party cookie.</p><h2 id="what-a-deployment-can-t-contain" tabindex="-1">What a deployment can&#39;t contain <a class="header-anchor" href="#what-a-deployment-can-t-contain" aria-label="Permalink to “What a deployment can&#39;t contain”">​</a></h2><p>A deploy is refused, before anything uploads, when the build:</p><ul><li>has more than 99,999 files, a file over 25 MiB, a file path over 768 UTF-8 bytes, or a manifest (the full file listing) over 88 MiB — publish fewer or smaller files;</li><li>has a path under <code>__primitive/</code> — that prefix is the platform&#39;s own, serving <code>config.json</code> and the sign-in proxy above;</li><li>has a <code>_headers</code> or <code>_redirects</code> file at its root — hosting reads neither.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./primitive-cli.html#hosting">CLI Reference</a></strong> — every <code>hosting</code> command</li><li><strong><a href="./deploying-to-production.html">Deploying to Production</a></strong> — deploy the web template to a cloud account of your own instead</li><li><strong><a href="./authentication.html">Authentication</a></strong> — Google OAuth, passkeys, and the rest of sign-in</li></ul>`,46)])])}const k=e(n,[["render",h]]);export{g as __pageData,k as default};
